BEGIN;

CREATE TABLE IF NOT EXISTS public.employee_role_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  role_code text,
  sector text NOT NULL DEFAULT 'custom',
  sector_label text NOT NULL DEFAULT 'عام',
  department_name text NOT NULL DEFAULT 'فريق التشغيل',
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  default_goal text NOT NULL DEFAULT '',
  mission text NOT NULL DEFAULT '',
  skills jsonb NOT NULL DEFAULT '[]'::jsonb,
  responsibilities jsonb NOT NULL DEFAULT '[]'::jsonb,
  tools jsonb NOT NULL DEFAULT '[]'::jsonb,
  permissions jsonb NOT NULL DEFAULT '["read_workspace","read_tasks","read_knowledge"]'::jsonb,
  default_budget_cents integer NOT NULL DEFAULT 5000 CHECK (default_budget_cents >= 0),
  provision_by_default boolean NOT NULL DEFAULT false,
  sort_order integer NOT NULL DEFAULT 100,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS id uuid DEFAULT gen_random_uuid();
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS role_code text;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS sector text NOT NULL DEFAULT 'custom';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS sector_label text NOT NULL DEFAULT 'عام';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS department_name text NOT NULL DEFAULT 'فريق التشغيل';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS name text NOT NULL DEFAULT 'موظف متخصص';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS description text NOT NULL DEFAULT '';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS default_goal text NOT NULL DEFAULT '';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS mission text NOT NULL DEFAULT '';
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS skills jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS responsibilities jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS tools jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS permissions jsonb NOT NULL DEFAULT '["read_workspace","read_tasks","read_knowledge"]'::jsonb;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS default_budget_cents integer NOT NULL DEFAULT 5000;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS provision_by_default boolean NOT NULL DEFAULT false;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 100;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.employee_role_templates ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
UPDATE public.employee_role_templates SET id=gen_random_uuid() WHERE id IS NULL;
ALTER TABLE public.employee_role_templates ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.employee_role_templates ALTER COLUMN id SET NOT NULL;

-- Normalize older manually-created arrays so the API and Supabase Edge Function
-- consume the same JSON contract regardless of the original column types.
ALTER TABLE public.employee_role_templates ALTER COLUMN skills DROP DEFAULT;
ALTER TABLE public.employee_role_templates ALTER COLUMN responsibilities DROP DEFAULT;
ALTER TABLE public.employee_role_templates ALTER COLUMN tools DROP DEFAULT;
ALTER TABLE public.employee_role_templates ALTER COLUMN permissions DROP DEFAULT;
ALTER TABLE public.employee_role_templates ALTER COLUMN skills TYPE jsonb USING COALESCE(to_jsonb(skills), '[]'::jsonb);
ALTER TABLE public.employee_role_templates ALTER COLUMN responsibilities TYPE jsonb USING COALESCE(to_jsonb(responsibilities), '[]'::jsonb);
ALTER TABLE public.employee_role_templates ALTER COLUMN tools TYPE jsonb USING COALESCE(to_jsonb(tools), '[]'::jsonb);
ALTER TABLE public.employee_role_templates ALTER COLUMN permissions TYPE jsonb USING COALESCE(to_jsonb(permissions), '["read_workspace","read_tasks","read_knowledge"]'::jsonb);
ALTER TABLE public.employee_role_templates ALTER COLUMN skills SET DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ALTER COLUMN responsibilities SET DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ALTER COLUMN tools SET DEFAULT '[]'::jsonb;
ALTER TABLE public.employee_role_templates ALTER COLUMN permissions SET DEFAULT '["read_workspace","read_tasks","read_knowledge"]'::jsonb;

UPDATE public.employee_role_templates
SET role_code = lower(sector) || '_' || COALESCE(NULLIF(regexp_replace(lower(name), '[^a-z0-9]+', '_', 'g'), ''), 'role') || '_' || substr(md5(COALESCE(id::text, sector || ':' || name)), 1, 8)
WHERE role_code IS NULL OR btrim(role_code) = '';

WITH duplicate_codes AS (
  SELECT id, role_code, row_number() OVER (PARTITION BY role_code ORDER BY id) AS ordinal
  FROM public.employee_role_templates
  WHERE role_code IS NOT NULL
)
UPDATE public.employee_role_templates AS templates
SET role_code = templates.role_code || '_' || substr(md5(COALESCE(templates.id::text, templates.name)), 1, 8)
FROM duplicate_codes
WHERE templates.id = duplicate_codes.id AND duplicate_codes.ordinal > 1;

CREATE UNIQUE INDEX IF NOT EXISTS employee_role_templates_role_code_uidx
  ON public.employee_role_templates(role_code) WHERE role_code IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS employee_role_templates_id_uidx
  ON public.employee_role_templates(id);
CREATE INDEX IF NOT EXISTS employee_role_templates_sector_department_idx
  ON public.employee_role_templates(sector, department_name, sort_order, name) WHERE active = true;

INSERT INTO public.employee_role_templates
  (role_code,sector,sector_label,department_name,name,description,default_goal,mission,skills,responsibilities,tools,permissions,default_budget_cents,provision_by_default,sort_order,active)
VALUES
('restaurant_operations_lead','restaurant','المطاعم','فريق تشغيل المطعم','قائد عمليات المطعم','تنسيق سير العمل اليومي ومتابعة مؤشرات الخدمة والمخزون؛ لا ينفذ معاملات مالية أو خارجية.','إعداد ملخص تشغيلي يومي يوضح أداء الخدمة والمخزون والاستثناءات مع توصيات قابلة للقياس.','قيادة المتابعة التشغيلية اليومية للمطعم وإحالة القرارات الحساسة إلى المسؤول.','["إدارة العمليات","تحليل المؤشرات","تنسيق الفرق"]','["مراجعة المهام التشغيلية","رصد التأخير والاستثناءات","إعداد ملخص يومي","تصعيد المخاطر إلى المدير"]','["data.analyze","report.create","tasks","quality.check","task.handoff"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,0,true),
('restaurant_service_coordinator','restaurant','المطاعم','فريق تشغيل المطعم','منسق خدمة العملاء والطلبات','مساندة فرز استفسارات الطلبات اعتمادًا على البيانات المتاحة؛ لا يرسل رسائل أو يغير طلبات.','تصنيف الاستفسارات وإعداد ملخص واضح للحالات التي تحتاج متابعة بشرية.','تقديم دعم تشغيلي منضبط لفرق خدمة المطعم مع حماية بيانات العملاء.','["خدمة العملاء","فرز الاستفسارات","كتابة الملخصات"]','["الاطلاع على الطلبات المرتبطة بالاستفسار","تصنيف الحالة","توثيق الملاحظات","تصعيد الشكاوى الحساسة"]','["customer.service","commerce.orders.list","commerce.customer.lookup","task.comment","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,10,true),
('restaurant_inventory_analyst','restaurant','المطاعم','فريق تشغيل المطعم','محلل مخزون المطعم','رصد مستويات المخزون والتنبيه إلى الانخفاضات اعتمادًا على بيانات الكتالوج.','تحديد أصناف المخزون التي تحتاج مراجعة وإعداد تقرير أسبوعي دون تنفيذ شراء.','تحسين وضوح المخزون وتقديم تنبيهات قابلة للتصرف مع بقاء قرارات الشراء بشرية.','["تحليل المخزون","التنبؤ التشغيلي","إعداد التقارير"]','["مراجعة مستويات الأصناف","رصد النواقص","إعداد قائمة مراجعة للمشتريات","قياس أثر التغيرات"]','["inventory.read","commerce.products.list","commerce.inventory.alerts","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,20,true),
('restaurant_marketing_analyst','restaurant','المطاعم','التسويق والنمو','محلل تسويق المطعم','تحليل الأداء التسويقي من البيانات المتاحة دون نشر محتوى أو إطلاق حملات.','إعداد تقرير شهري يربط مؤشرات الطلبات بالملاحظات التسويقية المتاحة.','تقديم توصيات تسويقية مدعومة بالبيانات دون إجراء نشر خارجي.','["تحليل الحملات","قياس الأداء","كتابة التقارير"]','["تحليل الاتجاهات","مقارنة الفترات","توثيق الافتراضات","اقتراح تجارب قابلة للقياس"]','["commerce.analytics.summary","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,100,true),
('restaurant_finance_analyst','restaurant','المطاعم','المالية والإيرادات','محلل إيرادات المطعم','إعداد قراءة تشغيلية للإيرادات والخصومات من سجل الطلبات؛ لا يقدم محاسبة قانونية أو ينفذ مدفوعات.','مقارنة الإيرادات والخصومات والطلبات المدفوعة خلال فترة محددة مع توثيق القيود.','توفير رؤية تشغيلية للإيرادات لا تحل محل دفتر الأستاذ أو المراجع المالي.','["تحليل الإيرادات","التسويات التشغيلية","التقارير المالية"]','["مراجعة مؤشرات الإيرادات","رصد الحالات غير الاعتيادية","شرح حدود البيانات","إعداد ملخص شهري"]','["finance.read","revenue.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,110,true),
('hospital_operations_coordinator','hospital','المستشفيات','فريق العمليات الإدارية','منسق العمليات الإدارية للمستشفى','مساندة تنسيق سير العمل الإداري ومتابعة مؤشرات الخدمة؛ لا يقدم تشخيصًا أو توصية علاجية.','إعداد ملخص تشغيلي أسبوعي عن المهام الإدارية والاستثناءات مع إحالتها للمسؤول.','دعم العمليات الإدارية فقط؛ لا يتخذ قرارات سريرية ولا يعالج بيانات طبية خارج الصلاحيات المعتمدة.','["تنسيق العمليات","تحليل الأداء","إدارة الاستثناءات"]','["متابعة المهام الإدارية","رصد التأخير","إعداد ملخصات تشغيلية","تصعيد الحالات الحساسة"]','["data.analyze","report.create","tasks","quality.check","task.handoff"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,0,true),
('hospital_patient_service_coordinator','hospital','المستشفيات','فريق العمليات الإدارية','منسق تجربة المستفيدين','تنظيم ملاحظات خدمة المستفيدين وتحويلها إلى حالات متابعة؛ لا يجيب عن الأسئلة الطبية.','تصنيف ملاحظات الخدمة وإعداد إحالات واضحة إلى الفريق البشري المختص.','دعم إداري غير سريري مع إحالة أي طلب صحي أو عاجل إلى الموظف البشري المختص.','["خدمة المستفيدين","تصنيف الحالات","التواصل المهني"]','["تلخيص طلبات الخدمة","تحديد نوع المتابعة","توثيق الملاحظات","تصعيد الحالات الصحية أو الطارئة"]','["customer.service","task.comment","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,10,true),
('hospital_quality_analyst','hospital','المستشفيات','فريق العمليات الإدارية','محلل الجودة التشغيلية','تحليل مؤشرات جودة العمليات الإدارية دون تقييم سريري للمرضى.','إعداد لوحة مؤشرات جودة تشغيلية شهرية مع مصادر القياس والقيود.','تحسين موثوقية العمليات الإدارية وإظهار فجوات البيانات بوضوح.','["تحليل الجودة","مراجعة السجلات","تحليل الأسباب"]','["مراجعة نتائج المهام","رصد التكرار والتأخير","إعداد تقرير جودة","اقتراح إجراءات تحسين غير سريرية"]','["quality.check","compliance.check","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,20,true),
('hospital_claims_coordinator','hospital','المستشفيات','المطالبات والتنسيق','منسق المطالبات الإدارية','تنظيم قوائم متابعة المطالبات وملاحظات المعالجة الإدارية؛ لا يقدم استشارة تأمينية أو مالية ملزمة.','إنتاج قائمة متابعة يومية للمطالبات التي تحتاج إلى مراجعة موظف مختص.','دعم سير العمل الإداري للمطالبات مع تصعيد القرارات المالية للبشر.','["تنسيق المطالبات","مراجعة البيانات","إدارة المتابعة"]','["تصنيف عناصر المتابعة","توثيق النواقص","إعداد قائمة حالات","تصعيد الاستثناءات"]','["tasks","data.analyze","report.create","task.comment"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,100,true),
('hospital_procurement_analyst','hospital','المستشفيات','المشتريات والإمداد','محلل الإمداد التشغيلي','مراجعة مؤشرات توفر المستلزمات وتقديم تنبيهات للمراجعة البشرية دون تنفيذ شراء.','إعداد ملخص أسبوعي عن أصناف الإمداد التي تحتاج تدقيقًا أو إعادة تخطيط.','مساندة تخطيط الإمداد دون إصدار أوامر شراء أو تغيير مورد.','["تحليل الإمداد","إدارة المخزون","التقارير"]','["مراجعة مستويات الأصناف","رصد النواقص","اقتراح أولويات المراجعة","توثيق الافتراضات"]','["inventory.read","commerce.inventory.alerts","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,110,true),
('hotel_operations_lead','hotel','الفنادق','فريق تجربة الضيوف','قائد عمليات الفندق','متابعة المهام التشغيلية ومؤشرات تجربة الضيوف والإشغال من البيانات المتاحة.','إعداد تقرير تشغيلي يومي يربط المهام المفتوحة ومؤشرات الخدمة والاستثناءات.','تنسيق العمليات الفندقية مع إبقاء قرارات التعويضات والتغييرات التجارية تحت موافقة بشرية.','["إدارة العمليات الفندقية","تحليل المؤشرات","تنسيق الفرق"]','["مراجعة المهام المفتوحة","رصد التأخير","إعداد تقرير يومي","تصعيد الحالات الحساسة"]','["tasks","quality.check","data.analyze","report.create","task.handoff"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,0,true),
('hotel_reservations_coordinator','hotel','الفنادق','فريق تجربة الضيوف','منسق الحجوزات وخدمة الضيوف','فرز استفسارات الحجوزات وسجلات الطلبات المتاحة دون تأكيد أو تعديل حجز.','تصنيف استفسارات الضيوف وتجهيز إحالة دقيقة إلى موظف الحجوزات.','دعم خدمة الضيوف مع عدم تغيير الحجز أو الالتزام بتعويض دون موافقة بشرية.','["خدمة الضيوف","فرز الاستفسارات","توثيق الحالات"]','["تلخيص استفسار الضيف","جمع معلومات المتابعة المسموح بها","توثيق الحالة","تصعيد الطلبات الخاصة"]','["customer.service","commerce.orders.list","task.comment","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,10,true),
('hotel_occupancy_analyst','hotel','الفنادق','فريق تجربة الضيوف','محلل الإشغال والإيرادات','تحليل اتجاهات الإشغال والإيرادات من البيانات التشغيلية المتاحة دون تغيير الأسعار.','إعداد ملخص أسبوعي لاتجاهات الإشغال والإيراد مع توضيح جودة البيانات.','تقديم تحليلات دعم القرار؛ لا يغير الأسعار أو سياسات الحجز.','["تحليل الإشغال","تحليل الإيرادات","التنبؤ"]','["مقارنة الفترات","رصد الاتجاهات","شرح القيود","إعداد توصيات للمدير"]','["commerce.analytics.summary","finance.read","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,20,true),
('hotel_guest_experience_analyst','hotel','الفنادق','تجربة الضيوف','محلل تجربة الضيوف','تلخيص ملاحظات الضيوف ومؤشرات الخدمة وتحديد موضوعات التحسين.','إنتاج تقرير شهري بأكثر موضوعات الملاحظات تكرارًا وفرص التحسين.','استخدام بيانات الخدمة المصرح بها فقط، وإخفاء البيانات الشخصية عند إعداد التقارير.','["تحليل تجربة العملاء","تصنيف النصوص","التقارير"]','["تجميع الملاحظات","تصنيف الموضوعات","رصد تكرار الشكاوى","اقتراح تحسينات قابلة للقياس"]','["customer.service","data.analyze","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,100,true),
('hotel_housekeeping_coordinator','hotel','الفنادق','التدبير الفندقي','منسق التدبير الفندقي','تنظيم قوائم المهام اليومية ومتابعة الإنجاز على مستوى الفريق.','إعداد قائمة متابعة يومية بالمهام المتأخرة والاستثناءات.','تنسيق العمل الداخلي فقط دون تعديل الحجوزات أو سجلات الضيوف.','["تنسيق الفرق","إدارة المهام","الجودة"]','["تجميع المهام","تحديد الأولويات","متابعة الإنجاز","تصعيد التأخير"]','["tasks","quality.check","task.comment","report.create"]','["read_workspace","read_tasks","read_knowledge"]',5000,false,110,true),
('enterprise_executive_analyst','enterprise','الشركات','فريق التميز التنفيذي','مساعد تنفيذي رقمي','إعداد موجزات تشغيلية وإدارة متابعات داخلية دون إرسال مراسلات خارجية.','إنتاج موجز أسبوعي للقرارات والمهام والمخاطر مع مصادرها ومالكيها.','توفير دعم إداري قابل للمراجعة مع إبقاء الالتزامات الخارجية بيد المسؤول.','["إعداد الموجزات","تنسيق المتابعة","إدارة الأولويات"]','["تلخيص المهام المفتوحة","رصد القرارات المعلقة","إعداد موجز تنفيذي","توجيه المتابعة للمالك المناسب"]','["tasks","report.create","task.comment","task.handoff"]','["read_workspace","read_tasks","read_knowledge"]',5000,true,0,true),
