ON CONFLICT (role_code) WHERE role_code IS NOT NULL DO UPDATE SET
  sector=EXCLUDED.sector,sector_label=EXCLUDED.sector_label,department_name=EXCLUDED.department_name,
  name=EXCLUDED.name,description=EXCLUDED.description,default_goal=EXCLUDED.default_goal,mission=EXCLUDED.mission,
  skills=EXCLUDED.skills,responsibilities=EXCLUDED.responsibilities,tools=EXCLUDED.tools,permissions=EXCLUDED.permissions,
  default_budget_cents=EXCLUDED.default_budget_cents,provision_by_default=EXCLUDED.provision_by_default,
  sort_order=EXCLUDED.sort_order,active=EXCLUDED.active,updated_at=now();

ALTER TABLE public.ai_employees ADD COLUMN IF NOT EXISTS role_code text;
CREATE INDEX IF NOT EXISTS idx_ai_employees_workspace_role_code_active
  ON public.ai_employees(workspace_id, role_code) WHERE status='active' AND role_code IS NOT NULL;

ALTER TABLE public.employee_role_templates ENABLE ROW LEVEL SECURITY;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.employee_role_templates FROM anon, authenticated;
GRANT SELECT ON public.employee_role_templates TO authenticated, service_role;
GRANT INSERT, UPDATE, DELETE ON public.employee_role_templates TO service_role;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='employee_role_templates' AND policyname='employee_role_templates_active_read') THEN
    EXECUTE 'CREATE POLICY employee_role_templates_active_read ON public.employee_role_templates FOR SELECT TO authenticated USING (active=true)';
  END IF;
END $$;

COMMIT;
